import React, { useState } from 'react';

const TodoList = ({ todos }) => {
  return (
    <div>
      <h1>Todo List</h1>
      <form onSubmit={(e) => {
        const newTodo = e.target.todo.value;
        todos.push({ text: newTodo });
        setTodos(todos);
      }}>
        <input type="text" name="todo" />
        <button type="submit">Add Todo</button>
        <ul>
          {todos.map((todo, index) => (
            <li key={index}>
              <input type="checkbox" checked={todo.complete} onChange={() => todos[index].complete = !todos[index].complete} />
              <span style={{ textDecoration: todos[index].complete ? 'line-through' : 'none' }}>
                {todos[index].text}
              </span>
            </li>
          ))}
        </ul>
      </form>
    </div>
  );
};

const NAME_1 = ({ todos }) => {
  return (
    <div>
      <TodoList todos={todos} />
      <button onClick={() => setTodos([])}>Remove All Completed Todos</button>
      <button onClick={() => setTodos([{ text: 'Add Todo', complete: true }])}>Add New Todo</button>
    </div>
  );
};

const rootElement = document.getElementById('root');
ReactDOM.render(<NAME_1 todos={[]} />, rootElement);

